param([Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
$inputs=@(@(),@(63),@(0xfffd),@(65,66),@(0),@(0xd800,0xdc00),@(0xdbff,0xdfff),@(65,0xd800,0xdc00,66),@(0xd800),@(0xdc00),@(0xd800,65),@(65,0xdc00),@(0xd800,0xd800),@(0xdc00,0xdc00),@(0xdc00,0xd800));$rows=@()
foreach($direction in @('Encoder','Decoder')){$replacementType=[type]("System.Text.${direction}ReplacementFallback");$exceptionType=[type]("System.Text.${direction}ExceptionFallback")
 foreach($inputId in -2..($inputs.Count-1)){$arguments=[object[]]::new(1);if($inputId -ge 0){$arguments[0]=[string]::new([char[]][int[]]$inputs[$inputId])}
  try{$fallback=if($inputId -eq -2){[Activator]::CreateInstance($replacementType)}else{[Activator]::CreateInstance($replacementType,$arguments)};$same=[Activator]::CreateInstance($replacementType,[object[]]@($fallback.DefaultString));$different=[Activator]::CreateInstance($replacementType,[object[]]@('different replacement'));$opposite=if($direction -eq 'Encoder'){[Text.DecoderReplacementFallback]::new($fallback.DefaultString)}else{[Text.EncoderReplacementFallback]::new($fallback.DefaultString)}
   $result=[ordered]@{ok=$true;defaultUnits=[int[]][char[]]$fallback.DefaultString;maxCharCount=$fallback.MaxCharCount;equalsSelf=$fallback.Equals($fallback);equalsEquivalent=$fallback.Equals($same);equalsDifferent=$fallback.Equals($different);equalsOpposite=$fallback.Equals($opposite);equalsNull=$fallback.Equals($null);equalHashInvariant=($fallback.GetHashCode() -eq $same.GetHashCode());bufferType=$fallback.CreateFallbackBuffer().GetType().FullName}}
  catch{$e=$_.Exception;while(($e -is [Management.Automation.RuntimeException] -or $e -is [Reflection.TargetInvocationException]) -and $null -ne $e.InnerException){$e=$e.InnerException};$result=[ordered]@{ok=$false;exception=$e.GetType().FullName;hResult=$e.HResult;paramName=$e.ParamName}}
  $rows+=[ordered]@{direction=$direction;inputId=$inputId;result=$result}
 }
}
$singletons=@()
foreach($direction in @('Encoder','Decoder')){foreach($kind in @('Replacement','Exception')){
 $baseType=[type]("System.Text.${direction}Fallback");$property=$baseType.GetProperty($kind+'Fallback');$fallback=$property.GetValue($null);$again=$property.GetValue($null);$other=[Activator]::CreateInstance($fallback.GetType())
 $singletons+=[ordered]@{direction=$direction;kind=$kind;type=$fallback.GetType().FullName;singleton=[object]::ReferenceEquals($fallback,$again);maxCharCount=$fallback.MaxCharCount;defaultUnits=$(if($kind -eq 'Replacement'){,[int[]][char[]]$fallback.DefaultString}else{$null});equalsNew=$fallback.Equals($other);equalsNull=$fallback.Equals($null);equalHashInvariant=($fallback.GetHashCode() -eq $other.GetHashCode());bufferType=$fallback.CreateFallbackBuffer().GetType().FullName}
}}
$profiles=@();foreach($emit in @($false,$true)){foreach($strict in @($false,$true)){$e=[Text.UTF8Encoding]::new($emit,$strict);$other=[Text.UTF8Encoding]::new($emit,$strict);$clone=[Text.Encoding]$e.Clone();$profiles+=[ordered]@{emit=$emit;strict=$strict;encoderType=$e.EncoderFallback.GetType().FullName;decoderType=$e.DecoderFallback.GetType().FullName;encoderUnits=$(if(-not $strict){,[int[]][char[]]$e.EncoderFallback.DefaultString}else{$null});decoderUnits=$(if(-not $strict){,[int[]][char[]]$e.DecoderFallback.DefaultString}else{$null});encoderMax=$e.EncoderFallback.MaxCharCount;decoderMax=$e.DecoderFallback.MaxCharCount;encoderShared=[object]::ReferenceEquals($e.EncoderFallback,$other.EncoderFallback);decoderShared=[object]::ReferenceEquals($e.DecoderFallback,$other.DecoderFallback);encoderCloneShared=[object]::ReferenceEquals($e.EncoderFallback,$clone.EncoderFallback);decoderCloneShared=[object]::ReferenceEquals($e.DecoderFallback,$clone.DecoderFallback)}}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();inputs=$inputs;constructors=$rows;singletons=$singletons;utf8Profiles=$profiles;qualification='SELECTED_FALLBACK_OBJECT_DEFAULTS_AND_CONSTRUCTORS_ONLY; BUFFER_CUSTOMIZATION_HASH_ALGORITHM_SOURCE_ABI_AND_TASK_ACCEPTANCE_OPEN'}
[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 11)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS pinned fallback objects: $($rows.Count) constructors, four singletons and four UTF-8 profiles"
